<?php require_once __DIR__.'/../../includes/bootstrap.php'; if(current_user()) redirect('user/dashboard/index.php'); $pageTitle='Request account'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$pass=$_POST['password']??'';$company=trim($_POST['company_name']??'');$phone=trim($_POST['phone']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Please provide valid details and a password of at least 8 characters.';else{try{$s=db()->prepare('INSERT INTO users(full_name,email,password_hash,phone,company_name,account_status) VALUES(?,?,?,?,?,"pending")');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$phone,$company]);$uid=(int)db()->lastInsertId();$rid=(int)db()->query("SELECT id FROM roles WHERE name='Registered User'")->fetchColumn();db()->prepare('INSERT INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$uid,$rid]);db()->prepare('INSERT INTO user_notification_preferences(user_id) VALUES(?)')->execute([$uid]);audit('registration','user',$uid);flash('success','Account request submitted. Management can approve the account before booking access is enabled.');redirect('public/auth/login.php');}catch(PDOException $e){$error=$e->getCode()==='23000'?'That email address is already registered.':'Unable to create account request.';}}} require __DIR__.'/../../includes/header.php'; ?><section class="auth-shell"><div class="auth-card"><div class="eyebrow">Guest access</div><h1>Request an account</h1><p>Approved accounts can create and manage venue bookings.</p><?php if($error): ?><div class="badge badge-red" style="margin-bottom:15px"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field full"><label>Full name</label><input name="full_name" required></div><div class="field"><label>Email</label><input type="email" name="email" required></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field full"><label>Company</label><input name="company_name"></div><div class="field full"><label>Password</label><input type="password" name="password" minlength="8" required></div></div><button class="btn btn-gold" style="width:100%;margin-top:20px">Submit request</button></form></div></section><?php require __DIR__.'/../../includes/footer.php'; ?>
